BANK={clip:r['source_bank'] for clip,r in SOURCES.items()}
def assign(p,clip):
    r=SOURCES[clip]
    p.update(donor=clip,source_bank=r['source_bank'],source_sha256=r['animation_sha256'],source_range=None,loop=False)
    if clip in AIR_ALIASES:p['source_aliases']=AIR_ALIASES[clip]
    return p

def get_plan(profile):
    base=deepcopy(previous_plan(0))
    for p in base:
        if p['normal_slot'] in [102,103,104]:assign(p,{102:'407',103:'352',104:'353'}[p['normal_slot']])
    if not profile:return base
    if profile==5:
        p=next(p for p in base if p['normal_slot']==10)
        p.update(donor='504',source_range=None,source_bank='p02ex_157.arc',loop=False,action='airborne dodge overlay')
        return [p]
    ground,air=SETS[profile-1];result=[]
    for p in base:
        slot=p['normal_slot']
        if not 98<=slot<=104:continue
        index={98:0,99:1,100:1,101:2,102:0,103:1,104:2}[slot]
        clip=(ground if slot<=101 else air)[index]
        result.append(assign(p,clip))
    return result
